// Renders app/legacy/body.tsx to a static HTML string and writes it to
// app/legacy/body-html.ts. The page serves that string opaquely (see
// app/page.tsx) so React creates zero fibers for the legacy tree and legacy
// load-time DOM mutations can never cause hydration mismatches.
//
// Why a committed generated file instead of renderToStaticMarkup in page.tsx?
// Next.js rejects `react-dom/server` imports inside Server Components at
// build time, so the render happens here in plain Node (same call the test
// helper uses) and the app imports only the resulting string.
//
// Runs automatically via the predev/prebuild/prebuild:next hooks; CI fails
// on drift (git diff). Deterministic: same body.tsx bytes in, same
// body-html.ts bytes out.
import ts from 'typescript';
import { readFileSync, unlinkSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { fileURLToPath, URL } from 'node:url';

const require = createRequire(import.meta.url);
const root = fileURLToPath(new URL('..', import.meta.url));
const sourcePath = fileURLToPath(new URL('../app/legacy/body.tsx', import.meta.url));
const outPath = fileURLToPath(new URL('../app/legacy/body-html.ts', import.meta.url));
const tmpPath = fileURLToPath(new URL('../app/legacy/.body-render.tmp.cjs', import.meta.url));

const source = readFileSync(sourcePath, 'utf8');
const { outputText, diagnostics } = ts.transpileModule(source, {
  compilerOptions: {
    jsx: ts.JsxEmit.ReactJSX,
    module: ts.ModuleKind.CommonJS,
    target: ts.ScriptTarget.ES2020,
  },
  fileName: 'body.tsx',
});
const errors = (diagnostics ?? []).filter((d) => d.category === ts.DiagnosticCategory.Error);
if (errors.length > 0) {
  const message = errors.map((d) => ts.flattenDiagnosticMessageText(d.messageText, ' ')).join('; ');
  throw new Error(`cannot transpile app/legacy/body.tsx: ${message}`);
}

try {
  writeFileSync(tmpPath, outputText);
  const { default: LegacyBody } = require(tmpPath);
  const React = require('react');
  const { renderToStaticMarkup } = require('react-dom/server');
  const html = renderToStaticMarkup(React.createElement(LegacyBody));
  const out =
    '// GENERATED by scripts/render-legacy-body.mjs — do not edit.\n' +
    '// Source: app/legacy/body.tsx. Regen: npm run render:body (also runs via\n' +
    '// predev/prebuild hooks; CI fails on drift). Served opaquely so React\n' +
    '// creates zero fibers for the legacy tree (see app/page.tsx).\n' +
    `export const LEGACY_BODY_HTML: string = ${JSON.stringify(html)};\n`;
  writeFileSync(outPath, out);
  console.log(`rendered legacy body: ${html.length} bytes -> ${outPath.replace(root, '')}`);
} finally {
  try {
    unlinkSync(tmpPath);
  } catch {
    // Already gone (or never written) — nothing to clean up.
  }
}
